\draw[curveBlue,line width=0.8pt,domain=0:6.283185,samples=181] plot (\x,{2*cos((\x-pi/6)*180/pi)});
\fill[curveBlue] (0,{sqrt(3)}) circle (1.3pt);
\fill[curveBlue] ({2*pi},{sqrt(3)}) circle (1.3pt);
